 open(tab='street'){if(this.hooks.mode()==='loading'||this.hooks.mode()==='title')return;this.stopReel();this.tab=tab;this.selected=null;this.prior=this.hooks.mode();this.hooks.pause();this.opened=true;this.render();if(!$('#dayPanel').open)$('#dayPanel').showModal();this.save();}
 close(){this.releaseCast();this.sceneRun=null;if($('#dayPanel').open)$('#dayPanel').close();this.opened=false;this.hooks.focus(null);this.hooks.resume(this.prior);}
 trackCast(e){const location=this.location(e);this.castLease={id:e.id,location:{...location},closest:this.distance(e),wasNear:this.distance(e)<=8};}
 releaseCast(){this.castLease=null;if(this.following){this.following=null;this.hooks.clearRoute?.();}this.hooks.releaseScene?.();}
 maintainCast(){const id=this.castLease?.id||this.following;if(!id)return;const e=this.available().find(e=>e.id===id);if(!e){this.releaseCast();return;}if(!this.castLease||this.opened)return;const d=this.distance(e),lease=this.castLease;lease.closest=Math.min(lease.closest,d);lease.wasNear||=d<=8;if((lease.wasNear&&d>14)||d>lease.closest+12)this.releaseCast();}
