 collect(){const events=this.state.events||[];if(events.length>this.lastEvent){const fresh=events.slice(this.lastEvent);const event=[...fresh].reverse().find(e=>e.text||e.message||e.title);if(event)this.news=event.text||event.message||event.title;this.lastEvent=events.length;}}
 renderRibbon(){this.maintainCast();const phase=this.state.phase?.label||this.state.phase?.id||this.state.phase||'Morning';$('#dayClock').textContent=this.time();$('#dayPhase').textContent=String(phase).replaceAll('_',' ');$('#dayNews').textContent=escalationHeadline(this.state)||this.news||'Friends arrive. Other stories are unfolding.';const nearest=this.available().filter(e=>this.distance(e)<7).sort((a,b)=>this.distance(a)-this.distance(b))[0];this.nearby=nearest;$('#sceneAction').classList.toggle('hidden',!nearest);if(nearest){$('#sceneAction').textContent='V · '+nearest.title;$('#sceneAction').onclick=()=>this.begin(nearest.id);} }
 begin(id){const e=this.available().find(e=>e.id===id);if(!e)return;if(this.distance(e)>8){this.follow(id);return;}const ready=this.hooks.castReady?.(e);if(ready===false||ready?.ready===false){if(this.opened)this.close();this.following=null;this.trackCast(e);this.hooks.prepare?.(e,this.location(e));this.hooks.toast(ready?.reason||'Your friends are coming over. V starts the exchange when they arrive.');return;}this.following=null;this.trackCast(e);this.open('street');this.tab='scene';this.selected=id;this.sceneRun=createSceneRun(e);this.beatElapsed=0;this.render();this.performBeat(e);this.hooks.focus(this.location(e));}
