 commitChoice(id,choice){const e=this.encounter(id),c=e?.choices.find(c=>c.id===choice);if(!e||!c)return;const result=actWorld(this.state,id,choice,{district:this.location(e).district||e.district});if(!result?.ok){this.hooks.toast(result?.reason||'The situation has changed.');this.selected=null;this.render();return;}this.following=null;this.hooks.clearRoute?.();this.collect();this.save();this.hooks.consequence?.(result,c,this.state);this.reels.push({id:`${id}-${this.state.time}`,title:e.title,line:c.line||c.response||c.label,choice:c.label,time:this.time(),location:this.location(e),actor:e.actorId||e.actor||e.participants?.[0],cinematic:e.presentation||e.cinematic||e.reel,encounter:id,beats:[...(e.staging?.setup?.length?[e.staging.setup[0]]:[]),...(c.responseBeats||[{speaker:e.actorId,line:c.line||c.label}])]});this.close();this.hooks.toast('Moment saved to your feed.');this.save();}
 playReel(reel){this.cinema={...reel,elapsed:0,duration:Math.max(7,Math.min(10,(reel.beats?.length||1)*2.4)),beatIndex:0};$('#reelOverlay').classList.remove('hidden');$('#reelSpeaker').textContent=reel.time+' · '+(reel.actor||'THE GROUP CHAT');$('#reelTitle').textContent=reel.title;$('#reelCaption').textContent=reel.beats?.[0]?.line||reel.line;this.hooks.focus(reel.location);this.hooks.scene?.({...reel,cinematic:{...reel.cinematic,duration:this.cinema.duration}});this.hooks.sting?.();}
